def preencher_estado(apps, schema_editor):
    """
    Lojas existentes: activa → 'ativa'. Inactiva → 'suspensa' se já tinha sido aprovada
    (há uma notificação 'loja_aprovada' para ela: foi desactivada depois), senão 'pendente'.
    """
    Loja        = apps.get_model('app', 'Loja')
    Notificacao = apps.get_model('app', 'Notificacao')
    aprovadas = set(Notificacao.objects.filter(tipo='loja_aprovada', loja__isnull=False)
                    .values_list('loja_id', flat=True))
    for loja in Loja.objects.all():
        if loja.ativa:
            estado = 'ativa'
        elif loja.pk in aprovadas:
            estado = 'suspensa'
        else:
            estado = 'pendente'
        Loja.objects.filter(pk=loja.pk).update(estado=estado)


